head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst72000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst72000.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "slc_selYear", attr: "__items", fn: function () { return [[String((dma_pageContext.get("targetYear") ?? "")), String((dma_pageContext.get("targetYear") ?? ""))]]; } },
        { childId: "slc_selMonth", attr: "__items", fn: function () { return [["", String((dma_pageContext.get("j") ?? ""))]]; } },
        { childId: "imgMonth", attr: "name", fn: function () { return "imgMonth" + String((dma_pageContext.get("idNumber") ?? "")); } },
        { childId: "imgMonth", attr: "toolTip", fn: function () { return String((dma_pageContext.get("idx") ?? "")) + "월"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((dma_pageContext.get("idx") ?? "")) + "월"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.fnInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst72000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_selMonth_onchange
 * @description slc_selMonth 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_selMonth_onchange = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.fnCalCheck(selfVar.value)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst72000.slc_selMonth_onchange' }); }
};

/**
 * @method
 * @name imgMonth_onclick
 * @description imgMonth 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.imgMonth_onclick = async function(e){
    try {
        await scwin.fnCalCheck('' + dma_pageContext.get("idNumber") + ''); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst72000.imgMonth_onclick' }); }
};

/**
 * @method
 * @name btn_fnCalcSearch_onclick
 * @description btn_fnCalcSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnCalcSearch_onclick = async function(e){
    try {
        await scwin.fnCalcSearch(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst72000.btn_fnCalcSearch_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnCalcSearch_ajaxsubmit
 * @description fn Calc Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnCalcSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnCalcSearch_ajaxsubmit",
        method: "post",
        action: "/listinvstg/pubofrschdl.do",
        ref: "dma_fnCalcSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    await scwin.fnCalcSearch();
};

/**
 * @method
 * @name fnCalcSearch
 * @description fn Calc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCalcSearch = async function () {
    $c.util.getComponent("dma_fnCalcSearchAjaxsubmitReq").set("method", "searchPubofrScholCalnd");
    $c.util.getComponent("dma_fnCalcSearchAjaxsubmitReq").set("forward", "pubofrSchol_sub");
    await scwin.tx_fnCalcSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
};

/**
 * @method
 * @name fnCalCheck
 * @description fn Cal Check 처리
 * @param {*} val val
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCalCheck = async function (val) {
    for (let idx = 1; idx <= 12; idx++) {
        let classid = "ord-";
        if ((idx - 1) >= 10) {
            classid += (idx - 1);
        } else {
            classid += "0" + (idx - 1);
        }
        if (val === idx) {
            classid += " active";
        }
        let idName = "imgMonth";
        if (idx >= 10) {
            idName += idx;
        } else {
            idName += "0" + idx;
        }
        $('#searchForm').find('a[name="' + idName + '"]').attr('class', classid);
    }
    $("#searchForm").find("select[name=slc_selMonth]").val(val);
    await scwin.fnCalcSearch();
};

/**
 * @method
 * @name fnDetailView
 * @description fn Detail View 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {void}
 * @hidden N
 */
scwin.fnDetailView = function (bzProcsNo) {
    const url = "/listinvstg/pubofrprogcomdetail.do?method=searchProgComDetailMain&bzProcsNo=" + bzProcsNo;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), { id: "공모기업현황상세", scrollbars: true, resizable: false, width: "865", height: "700", type: "pageFramePopup" }, {});
};
